#include <bits/stdc++.h>
using namespace std;struct A{int w,d,n;};struct T{int old,p,off;};
int main(int argc,char**argv){int K=atoi(argv[3]),BOUND=atoi(argv[4]);map<int,array<A,2>>rows;map<int,vector<int>>pat;map<int,set<int>>incdirs;int q,b,w,n;char d;ifstream ts(argv[1]);while(ts>>q>>b>>w>>d>>n){rows[q][b]={w,d=='R'?1:-1,n};incdirs[n].insert(d=='R'?1:-1);}int p;ifstream ps(argv[2]);while(ps>>q>>p)pat[q].push_back(p);long long pairs=0,trials=0,combos=0,hits=0;
for(auto &[a,ar]:rows){if(incdirs[a].size()!=1)continue;int off=-2**incdirs[a].begin();for(auto &[keep,kr]:rows){if(a==keep)continue;++pairs;vector<T>tests[2];for(int old:{a,keep})for(int p:pat[old]){int o=old==a?off:0;tests[p>>(o+K)&1].push_back({old,p,o});}for(auto&v:tests)sort(v.begin(),v.end(),[](T&a,T&b){return a.p<b.p||(a.p==b.p&&a.old<b.old);});array<A,2>acts;int known;
auto check=[&](T tc){A old=rows[tc.old][tc.p>>K&1];int tq=old.n==a?keep:old.n,th=old.d+(old.n==a?off:0),tt=(tc.p&~(1<<K))|(old.w<<K),q=keep,h=tc.off,t=tc.p;
for(int st=0;st<=BOUND;st++){if(st&&q==tq&&h==th&&t==tt)return 1;if(st==BOUND||h<-K||h>K||!rows.count(q))return 0;int b=t>>(h+K)&1;A op;if(q==keep){if(!(known>>b&1))return 2;op=acts[b];}else op=rows[q][b];t=(t&~(1<<(h+K)))|(op.w<<(h+K));if(op.n==a){op.n=keep;op.d=-op.d;}h+=op.d;q=op.n;}return 0;};
vector<A> choices[2];bool possible=true;for(int b:{0,1}){known=1<<b;for(auto &[n,nr]:rows){if(n==a)continue;for(int w:{0,1})for(int d:{-1,1}){++trials;acts[b]={w,d,n};bool ok=true;for(auto tc:tests[b])if(!check(tc)){ok=false;break;}if(ok)choices[b].push_back(acts[b]);}}if(choices[b].empty()){possible=false;break;}}if(!possible)continue;known=3;for(A z:choices[0])for(A o:choices[1]){++combos;acts={z,o};bool ok=true;for(int b:{0,1}){for(auto tc:tests[b])if(check(tc)!=1){ok=false;break;}if(!ok)break;}if(ok){++hits;cout<<"{\"remove\":"<<a<<",\"keep\":"<<keep<<",\"offset\":"<<off<<",\"actions\":[["<<z.w<<','<<z.d<<','<<z.n<<"],["<<o.w<<','<<o.d<<','<<o.n<<"]]}"<<endl;}}
}cerr<<"Q "<<a<<" pairs "<<pairs<<" trials "<<trials<<" combos "<<combos<<" hits "<<hits<<endl;}cerr<<"DONE pairs "<<pairs<<" trials "<<trials<<" combos "<<combos<<" hits "<<hits<<endl;}
